import openpyxl, os

in_path = os.environ['IN_XLSX']
out_path = os.environ['OUT_XLSX']

wb = openpyxl.load_workbook(in_path)
ws = wb['Worksheet1']

# Collect rows to keep: header + rows where column B starts with 'H' or 'A'
rows_to_keep = []
for row in ws.iter_rows(min_row=1, max_row=ws.max_row, min_col=1, max_col=10):
    if row[0].row == 1:
        rows_to_keep.append([cell.value for cell in row])
    else:
        b_val = row[1].value
        if b_val is not None:
            s = str(b_val)
            if s.startswith('H') or s.startswith('A'):
                rows_to_keep.append([cell.value for cell in row])

print(f"Rows to keep: {len(rows_to_keep)}")

# Clear all data rows (rows 2 through max_row)
for row in ws.iter_rows(min_row=2, max_row=ws.max_row, min_col=1, max_col=10):
    for cell in row:
        cell.value = None

# Write back kept data rows (starting at row 2)
for i, data in enumerate(rows_to_keep[1:], start=2):
    for j, val in enumerate(data, start=1):
        ws.cell(row=i, column=j, value=val)

wb.save(out_path)
print(f"Done. Final row count: {ws.max_row}")
